import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry max_reduce_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 outer_size,
    .param .u32 reduce_size,
    .param .u32 inner_size,
    .param .u32 total_size
)
{
    .reg .u64 %rd<10>;
    .reg .u32 %r<20>;
    .reg .f32 %f<10>;
    .reg .pred %p<5>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.u32 %r1, [outer_size];
    ld.param.u32 %r2, [reduce_size];
    ld.param.u32 %r3, [inner_size];
    ld.param.u32 %r4, [total_size];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    mov.u32 %r5, %ctaid.x;
    mov.u32 %r6, %ntid.x;
    mov.u32 %r7, %tid.x;
    mad.lo.s32 %r8, %r5, %r6, %r7;

    setp.ge.s32 %p1, %r8, %r4;
    @%p1 bra DONE;

    div.s32 %r9, %r8, %r3;
    rem.s32 %r10, %r8, %r3;

    mul.lo.s32 %r11, %r2, %r3;
    mul.lo.s32 %r12, %r9, %r11;
    add.s32 %r13, %r12, %r10;

    mul.wide.s32 %rd4, %r13, 4;
    add.s64 %rd5, %rd1, %rd4;

    ld.global.f32 %f1, [%rd5];

    mov.u32 %r14, 1;
    mul.wide.s32 %rd6, %r3, 4;

LOOP:
    setp.ge.s32 %p2, %r14, %r2;
    @%p2 bra LOOPEND;

    add.s64 %rd5, %rd5, %rd6;
    ld.global.f32 %f2, [%rd5];
    max.f32 %f1, %f1, %f2;

    add.s32 %r14, %r14, 1;
    bra LOOP;

LOOPEND:
    mul.wide.s32 %rd7, %r8, 4;
    add.s64 %rd8, %rd2, %rd7;
    st.global.f32 [%rd8], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("max_reduce_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension,
    implemented with a custom PTX kernel.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float32, "Kernel specialized for float32 tensors."
        x = x.contiguous()

        dim = self.dim
        if dim < 0:
            dim = dim + x.dim()

        shape = list(x.shape)

        outer_size = 1
        for s in shape[:dim]:
            outer_size *= s

        reduce_size = shape[dim]

        inner_size = 1
        for s in shape[dim + 1:]:
            inner_size *= s

        out_shape = shape[:dim] + shape[dim + 1:]

        output = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        total_size = outer_size * inner_size

        module = _get_ptx_module()

        block_x = 256
        grid_x = (total_size + block_x - 1) // block_x
        if grid_x < 1:
            grid_x = 1

        module.launch(
            "max_reduce_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                output,
                i32(outer_size),
                i32(reduce_size),
                i32(inner_size),
                i32(total_size),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output

